function Orders(){
  const [o,setO]=useState<any[]>([]);

  useEffect(()=>{
    let live=true;
    async function load(){
      const u=await uid(); if(!u||!live)return;
      const {data,error}=await supabase.from('orders').select('*,order_items(*)').eq('user_id',u).order('created_at',{ascending:false});
      if(!error&&live)setO(data||[]);
    }
    load(); const timer=setInterval(load,4000);
    return()=>{live=false;clearInterval(timer)};
  },[]);

  return <>
    <main className="shop">
      <Top title={tr('Orders','ការបញ្ជាទិញ')}/>

      {o.map(x=>
        <div className="ordercard" key={x.id}>
          <div className="line">
            <b>#{x.order_number}</b>
            <Status s={x.status}/>
          </div>

          <small>
            {new Date(x.created_at).toLocaleString()}
          </small>

          {x.order_items?.map((i:any)=>
            <div className="miniitem" key={i.id}>
              <img src={i.product_image||''}/>
              <span>
                {i.product_name} × {i.quantity}
              </span>
              <b>{money(i.subtotal)}</b>
            </div>
          )}

          <div className="line total">
            <span>{tr('Total','សរុប')}</span>
            <b>{money(x.total)}</b>
          </div>
        </div>
      )}

      {!o.length&&<Empty text={tr('No orders yet.','មិនទាន់មានការបញ្ជាទិញ។')}/>}
    </main>

    <Nav/>
  </>;
}
