    <button type="button" className="abaPaymentButton" onClick={()=>setShowAba(true)}><span className="abaBadge">ABA</span><span><b>{tr('Pay with ABA','ទូទាត់តាម ABA')}</b><small>{tr('Open the YN Studio payment QR','បើក QR ទូទាត់របស់ YN Studio')}</small></span><ChevronRight/></button>
